@@ -0,0 +1,59 @@
+import { ChevronRightIcon } from "lucide-react";
+import type { StoryHop, StoryNav as StoryNavModel } from "../lib/story-nav.ts";
+import { Button } from "@/components/ui/button.tsx";
+import { cn } from "@/lib/utils.ts";
+import { Kbd } from "./Kbd.tsx";
+import { Kicker } from "./Kicker.tsx";
+
+export function StoryNav(props: { nav: StoryNavModel; onOpenGroup: (id: string) => void }) {
+  const previous = props.nav.previousPart;
+  const next = props.nav.nextPart;
+  if (previous === undefined && next === undefined) {
+    return null;
+  }
+  const label = props.nav.partTitle !== undefined ? `Part ${props.nav.partTitle}` : "This story";
+  return (
+    <nav
+      aria-label={label}
+      className="mt-6 flex items-start justify-between gap-3 border-t border-border pt-4"
+    >
+      <HopButton hop={previous} side="previous" onOpen={props.onOpenGroup} />
+      <HopButton hop={next} side="next" onOpen={props.onOpenGroup} />
+    </nav>
+  );
+}
+
+function HopButton(props: {
+  hop: StoryHop | undefined;
+  side: "previous" | "next";
+  onOpen: (id: string) => void;
+}) {
+  const { hop, side, onOpen } = props;
+  if (hop === undefined) {
+    return <span />;
+  }
+  const name = hop.partTitle ?? hop.title;
+  const kicker = side === "next" ? "Next part" : "Previous part";
+  const shortcut = side === "next" ? "}" : "{";
+  const direction = side === "next" ? "Next" : "Previous";
+  return (
+    <Button
+      type="button"
+      variant="ghost"
+      aria-label={`${direction} part: ${name}`}
+      className={cn(
+        "h-auto min-w-0 max-w-[calc(50%-0.375rem)] flex-col gap-1 px-2 py-2 font-normal whitespace-normal",
+        side === "previous" ? "items-start" : "items-end",
+      )}
+      onClick={() => onOpen(hop.id)}
+    >
+      <Kicker className="mb-0">{kicker}</Kicker>
+      <span className="flex min-w-0 items-center gap-1 text-foreground">
+        {side === "previous" ? <ChevronRightIcon className="size-4 shrink-0 rotate-180" /> : null}
+        <span className="min-w-0 text-left leading-snug">{name}</span>
+        {side === "next" ? <ChevronRightIcon className="size-4 shrink-0" /> : null}
+        <Kbd className="max-sm:hidden">{shortcut}</Kbd>
+      </span>
+    </Button>
+  );
+}

diff --git a/src/ui/lib/story-nav.ts b/src/ui/lib/story-nav.ts
new file mode 100644
index 0000000..4b85784
--- /dev/null
+++ b/src/ui/lib/story-nav.ts
@@ -0,0 +1,94 @@
+import { groupParts, isMixedReview, type Part } from "./parts.ts";
+
+export type StoryGroup = {
+  id: string;
+  title: string;
+  part?: string;
+  suggestedOrder?: number;
+  dependsOn?: readonly string[];
+};
+
+export type StoryHop = {
+  id: string;
+  title: string;
+  axis: "group" | "part";
+  partTitle?: string;
+};
+
+export type StoryNav = {
+  partTitle?: string;
+  previous?: StoryHop;
+  next?: StoryHop;
+  previousPart?: StoryHop;
+  nextPart?: StoryHop;
+  dependsOn: StoryHop[];
+  dependents: StoryHop[];
+};
+
+export function storyNav(groups: readonly StoryGroup[], groupId: string): StoryNav {
+  return storyNavFromParts(groups, groupParts(groups), groupId);
+}
+
+export function storyNavFromParts(groups: readonly StoryGroup[], parts: readonly Part[], groupId: string): StoryNav {
+  const byId = new Map(groups.map((group) => [group.id, group]));
+  const partIndex = parts.findIndex((part) => part.groupIds.includes(groupId));
+  const part = parts[partIndex];
+  if (part === undefined) {
+    return { dependsOn: [], dependents: [] };
+  }
+
+  const mixed = isMixedReview(parts);
+  const index = part.groupIds.indexOf(groupId);
+  const group = byId.get(groupId);
+  const previous = groupHop(byId, part.groupIds[index - 1]);
+  const next = groupHop(byId, part.groupIds[index + 1]);
+  const previousPart = mixed ? partHop(byId, parts[partIndex - 1]) : undefined;
+  const nextPart = mixed ? partHop(byId, parts[partIndex + 1]) : undefined;
+
+  return {
+    ...(part.title !== undefined ? { partTitle: part.title } : {}),
+    ...(previous !== undefined ? { previous } : {}),
+    ...(next !== undefined ? { next } : {}),
+    ...(previousPart !== undefined ? { previousPart } : {}),
+    ...(nextPart !== undefined ? { nextPart } : {}),
+    dependsOn: (group?.dependsOn ?? []).flatMap((id) => {
+      const hop = groupHop(byId, id);
+      return hop === undefined ? [] : [hop];
+    }),
+    dependents: groups.flatMap((item) => {
+      if (!(item.dependsOn ?? []).includes(groupId)) {
+        return [];
+      }
+      const hop = groupHop(byId, item.id);
+      return hop === undefined ? [] : [hop];
+    }),
+  };
+}
+
+function groupHop(byId: Map<string, StoryGroup>, id: string | undefined): StoryHop | undefined {
+  if (id === undefined) {
+    return undefined;
+  }
+  const group = byId.get(id);
+  if (group === undefined) {
+    return undefined;
+  }
+  return { id, title: group.title, axis: "group" };
+}
+
+function partHop(byId: Map<string, StoryGroup>, part: Part | undefined): StoryHop | undefined {
+  const id = part?.groupIds[0];
+  if (part === undefined || id === undefined) {
+    return undefined;
+  }
+  const group = byId.get(id);
+  if (group === undefined) {
+    return undefined;
+  }
+  return {
+    id,
+    title: group.title,
+    axis: "part",
+    ...(part.title !== undefined ? { partTitle: part.title } : {}),
+  };
+}

